insert into public.role_defaults (key, label, description, sort_order) values
  ('owner', 'Owner / Tenant Admin', 'Full unrestricted access across every location and configuration screen.', 0),
  ('hr-manager', 'HR Manager', 'Owns people data, onboarding, performance and leave across all locations.', 1),
  ('location-manager', 'Location Manager', 'Runs one or more locations: roster, timesheet approvals, compliance and staff.', 2),
  ('scheduler', 'Rostering Coordinator', 'Builds and optimises rosters, fills open shifts, no pay or approval rights.', 3),
  ('payroll', 'Payroll Officer', 'Approves and exports timesheets, manages awards, pay conditions and rates.', 4),
  ('supervisor', 'Team Supervisor', 'Day-to-day oversight of one area: view roster, first-tier timesheet approval.', 5),
  ('employee', 'Employee', 'Self-service only — own shifts, timesheets, leave, learning and recognition.', 6),
  ('agency-partner', 'Agency Partner', 'External staffing partner — sees broadcast shifts and submits candidates.', 7)
